"""Real Chromium UI regression against the Windows-facing local gateway."""
from pathlib import Path
import json,subprocess,time,re
from playwright.sync_api import sync_playwright,expect
root=Path(__file__).resolve().parents[1]
js="""import {login,call,sql} from './scripts/test-performance-api.mjs';import {readFileSync,writeFileSync} from 'node:fs';const f=JSON.parse(readFileSync('.runtime/sourcing/fixture.json'));const out={owner:await login(f.owner),manager:await login(f.manager),portal:await login(f.otherPortal,'c')};const p='/srm/v1/sourcing',cp='/client/c/srm/v1/sourcing',base={requestKey:crypto.randomUUID(),rowVersion:0,title:'W12–15浏览器竞价-'+Date.now(),category:'MACHINING',strategy:'AUCTION',currency:'CNY',deadline:Date.now()+600000,startAt:Date.now()-1000,supplierIds:[f.supplier,f.secondSupplier],lines:[{id:'BROWSE_LINE',material:'浏览器验收物料',quantity:1,delivery:'7天',fileIds:[]}],startingPrice:1000,minDecrement:10,antiSnipeMinutes:5};let auction=await call(p+'/rfqs',out.owner,base);auction=await call(p+'/rfqs/'+auction.id+'/publish',out.owner,{rowVersion:0});await call(p+'/rfqs/'+auction.id+'/recover',out.owner,{});out.browserAuction=auction;let rfq=await call(p+'/rfqs',out.owner,{...base,requestKey:crypto.randomUUID(),title:'W12–15浏览器审批-'+Date.now(),strategy:'COMPARE'});rfq=await call(p+'/rfqs/'+rfq.id+'/publish',out.owner,{rowVersion:0});const first=await login(f.portal,'c');for(const token of [first,out.portal])await call(cp+'/rfqs/'+rfq.id+'/quotes',token,{requestKey:crypto.randomUUID(),expectedRound:0,lines:[{lineId:'BROWSE_LINE',unitPrice:100,leadDays:7}],freight:0});sql('UPDATE SRM_SRC_RFQ SET DEADLINE_MS=1 WHERE ID=\"'+rfq.id+'\"');for(let i=0;i<30;i++){rfq=await call(p+'/rfqs/'+rfq.id,out.owner);if(rfq.status==='CLOSED')break;await new Promise(r=>setTimeout(r,300))}out.reviewAward=await call(p+'/rfqs/'+rfq.id+'/awards',out.owner,{requestKey:crypto.randomUUID(),supplierId:f.supplier,reason:'浏览器审批页面验收',noHistoryReason:'浏览器核验',discloseLoss:false});writeFileSync('.runtime/sourcing/browser-tokens.json',JSON.stringify(out),{mode:0o600});"""
subprocess.run(['node','--input-type=module','-e',js],cwd=root,check=True)
tokens=json.loads((root/'.runtime/sourcing/browser-tokens.json').read_text());f=json.loads((root/'.runtime/sourcing/fixture.json').read_text());checks=[]
with sync_playwright() as pw:
 browser=pw.chromium.launch(headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
 def page_for(token,realm='b'):
  context=browser.new_context(viewport={'width':1500,'height':1050});page=context.new_page();page.add_init_script("sessionStorage.setItem('srm-active-realm',"+json.dumps(realm)+");sessionStorage.setItem('srm-real-"+realm+"',"+json.dumps(token)+");");page.goto('http://localhost:18080/');page.get_by_role('button',name='◇　寻源与竞价',exact=True).click();expect(page.get_by_role('heading',name='寻源与竞价',level=1,exact=True)).to_be_visible();return page
 owner=page_for(tokens['owner']);checks.append('internal_sourcing_navigation')
 owner.get_by_label('寻源搜索').fill(f['rfq']);owner.get_by_role('button',name='查询',exact=True).click()
 # Search uses business title/number, so select retained record by querying its title.
 owner.get_by_label('寻源搜索').fill('W12–15验收-COMPARE');owner.get_by_role('button',name='查询',exact=True).click();expect(owner.locator('tbody tr').first).to_be_visible();owner.locator('tbody tr').first.get_by_role('button',name='打开询价',exact=True).click();owner.wait_for_function("!document.querySelector('.sourcing-panel .form-error') && document.querySelector('.sourcing-panel h4')");owner.wait_for_timeout(1000);expect(owner.get_by_role('heading',name='报价轮次')).to_be_visible();checks.append('rfq_detail_and_immutable_quote_history')
 owner.get_by_role('button',name='查看最新比价',exact=True).click();expect(owner.get_by_role('columnheader',name='综合分',exact=True)).to_be_visible(timeout=20000);checks.append('comparison_panel_real_performance')
 owner.get_by_role('button',name='新建询价',exact=True).click();title='W12–15浏览器草稿-'+str(int(time.time()));owner.wait_for_timeout(1000);owner.locator('label').filter(has_text='物料品类').locator('select').select_option('MACHINING');owner.get_by_label('标题',exact=True).fill(title);owner.get_by_label('物料名称',exact=True).fill('浏览器物料');owner.get_by_label('交付要求',exact=True).fill('10天');owner.get_by_label('搜索受邀供应商',exact=True).fill('W12–15验收无历史');owner.get_by_role('button',name='查询受邀供应商',exact=True).click();owner.locator('fieldset input[type=checkbox]').first.check();owner.get_by_role('button',name='保存草稿',exact=True).click();expect(owner.get_by_role('heading',name=title+' · 草稿',exact=True)).to_be_visible(timeout=15000);owner.get_by_role('button',name='编辑草稿',exact=True).click();expect(owner.get_by_label('标题',exact=True)).to_have_value(title);owner.get_by_role('button',name='添加物料',exact=True).click();owner.get_by_label('物料名称',exact=True).nth(1).fill('附加物料');owner.get_by_label('交付要求',exact=True).nth(1).fill('14天');owner.get_by_role('button',name='保存草稿',exact=True).click();expect(owner.get_by_role('button',name='发布邀请',exact=True)).to_be_visible();checks.append('create_and_edit_draft_in_browser')
 owner.wait_for_function("document.querySelector('.sourcing-panel').getAttribute('aria-busy')==='false'");owner.get_by_label('规格所属物料',exact=True).select_option(label='附加物料');owner.locator('.sourcing-panel input[type=file]').set_input_files({'name':'line-two-spec.pdf','mimeType':'application/pdf','buffer':b'%PDF-1.4\nline two specification\n%%EOF'});expect(owner.locator('form.src-card > div.src-card').nth(1)).to_contain_text('已绑定 1 份私有规格',timeout=15000);owner.get_by_role('button',name='保存草稿',exact=True).click();expect(owner.get_by_role('button',name='发布邀请',exact=True)).to_be_visible();checks.append('line_specific_private_spec_upload_and_supplier_candidate_search')
 owner.screenshot(path=str(root/'.runtime/sourcing/internal.png'),full_page=True)
 portal=page_for(tokens['portal'],'c');expect(portal.get_by_role('button',name='新建询价',exact=True)).to_have_count(0);portal.get_by_label('寻源搜索').fill('W12–15验收-COMPARE');portal.get_by_role('button',name='查询',exact=True).click();portal.locator('tbody tr').first.get_by_role('button',name='打开询价',exact=True).click();expect(portal.get_by_text('本轮定点已中选',exact=True)).to_be_visible();expect(portal.get_by_role('heading',name='人工风险评估')).to_have_count(0);checks.append('portal_private_award_result_and_role_controls')
 portal.get_by_label('寻源搜索').fill(tokens['browserAuction']['title']);portal.get_by_role('button',name='查询',exact=True).click();portal.locator('tbody tr').first.get_by_role('button',name='打开询价',exact=True).click();expect(portal.get_by_role('heading',name='实时竞价')).to_be_visible();expect(portal.get_by_text('已连接',exact=False)).to_be_visible(timeout=15000);checks.append('native_browser_stomp_connection_anonymous_board')
 portal.get_by_label('新的篮子总价',exact=True).fill('960');portal.get_by_role('button',name='发送竞价',exact=True).click();expect(portal.get_by_text('出价已持久保存，请以回执序号为准',exact=True)).to_be_visible(timeout=15000);expect(portal.get_by_text('本方报价 960',exact=False)).to_be_visible();checks.append('browser_bid_receipt_and_own_rank_update')
 portal.screenshot(path=str(root/'.runtime/sourcing/portal-auction.png'),full_page=True)
 manager=page_for(tokens['manager']);manager.get_by_role('button',name=re.compile(re.escape(tokens['reviewAward']['rfqTitle']))).click();expect(manager.get_by_text('推荐供方：',exact=False)).to_be_visible();manager.get_by_label('定点审批动作',exact=True).select_option('REASSIGN');manager.get_by_label('改派候选供应商',exact=True).select_option(f['secondSupplier']);expect(manager.get_by_label('改派候选供应商',exact=True)).to_have_value(f['secondSupplier']);checks.append('manager_named_candidate_selection_and_readable_review_basis');manager.screenshot(path=str(root/'.runtime/sourcing/manager-review.png'),full_page=True);response=manager.request.post('http://localhost:18080/api/srm/v1/sourcing/awards/'+tokens['reviewAward']['id']+'/withdraw',headers={'token':tokens['owner']});assert response.json()['code']==200
 browser.close()
(root/'docs/sourcing/browser-verification.json').write_text(json.dumps({'result':'passed','entry':'http://localhost:18080/','date':time.strftime('%Y-%m-%d'),'checks':checks},ensure_ascii=False,indent=2)+'\n')
print('PASS:',len(checks),'real browser sourcing checks')
